const input = Array.isArray($json) ? $json : [$json];
return input.map((record) => {
  const days = Number(record.lastTouchDays ?? 0);
  let nextAction = 'No follow-up needed today.';
  if (!record.adjusterAppointmentDate) nextAction = 'Ask homeowner if adjuster appointment has been scheduled.';
  else if (record.inspectionCompleted && !record.estimateSent) nextAction = 'Create estimate preparation task.';
  else if (days >= 7) nextAction = 'Send owner-approved claim status follow-up.';
  return { json: { ...record, nextAction } };
});
